const TRIAL_KEY='paesFullTrialV1';
let trialTimer=null;
function trialData(){try{return JSON.parse(localStorage.getItem(TRIAL_KEY)||'null')}catch{return null}}
function trialState(){let t=trialData();if(!t)return 'none';return Date.now()<Number(t.endsAt||0)?'active':'expired'}
function trialRemainingMs(){let t=trialData();return t?Math.max(0,Number(t.endsAt||0)-Date.now()):0}
function trialRemainingText(){let ms=trialRemainingMs(),h=Math.floor(ms/3600000),m=Math.floor((ms%3600000)/60000);return `${h} h ${m} min`}
function ensureTrialProfile(){let id='trial_full',profiles=getProfiles(),p=profiles.find(x=>x.id===id);if(!p){p={id,name:'Mi prueba FULL',goal:750,studyProfile:'completas',tests:[],guest:false,trial:true,created:new Date().toISOString()};profiles.push(p);saveProfiles(profiles)}setActiveId(id);return p}
function scheduleTrialExpiry(){clearTimeout(trialTimer);let left=trialRemainingMs();if(left>0)trialTimer=setTimeout(()=>trialExpiredScreen(),Math.min(left,2147483647))}
function startFullTrial(){let status=trialState();if(status==='expired'){trialExpiredScreen();return}if(status==='none'){let startedAt=Date.now();localStorage.setItem(TRIAL_KEY,JSON.stringify({startedAt,endsAt:startedAt+24*60*60*1000}))}commercialMode='trial';currentAccess=null;ensureTrialProfile();setNav(true);scheduleTrialExpiry();home()}
function commercialHome(){if(commercialMode==='member')return home();if(commercialMode==='trial'&&trialState()==='active')return home();return landing()}
function trialExpiredScreen(){clearTimeout(trialTimer);commercialMode='public';currentAccess=null;setNav(false);app.innerHTML=`<section class="loginWrap"><div class="card loginCard"><div class="expiredIcon">⏰</div><div class="eyebrow">PRUEBA FULL FINALIZADA</div><h1>Tu día de prueba terminó</h1><p>Durante 24 horas pudiste usar PAES Trainer con acceso completo. Para seguir estudiando, activa tu acceso por 1 año.</p><div class="licenseBox"><span>Acceso completo</span><b>$15.990</b><small>1 año · Todas las funciones</small></div><a class="waBtn" href="${whatsappUrl()}" target="_blank" rel="noopener">Comprar acceso por $15.990</a><button class="secondary full" onclick="loginScreen()">Ya tengo usuario</button><button class="ghost full" onclick="landing()">Volver</button></div></section>`;window.scrollTo(0,0)}
function trialAccount(){if(trialState()!=='active'){trialExpiredScreen();return}let p=getActiveProfile()||ensureTrialProfile(),g=getGame(),h=getHistory();app.innerHTML=`<h1>Mi prueba FULL</h1><section class="grid"><article class="card"><div class="eyebrow">1 DÍA DE PRUEBA FULL</div><h2>${esc(p.name)}</h2><div class="licenseBox"><span>Tiempo restante</span><b>${trialRemainingText()}</b><small>Al finalizar, la prueba se bloqueará automáticamente.</small></div><div class="meta"><span class="pill">🔥 ${g.streak} días</span><span class="pill">⭐ ${g.xp} XP</span><span class="pill">${h.length} sesiones</span></div><button class="secondary" onclick="editProfile()">Editar perfil de estudio</button></article><article class="card"><h3>Todo está desbloqueado</h3><p>Durante estas 24 horas puedes usar ensayos, generador, diagnóstico, historial, práctica de errores, rachas, XP y todas las pruebas PAES.</p><a class="waBtn" href="${whatsappUrl()}" target="_blank" rel="noopener">Comprar 1 año · $15.990</a></article></section><div class="toolbar"><button class="btn" onclick="home()">Volver al inicio</button></div>`;setTimeout(()=>window.PAES_RATINGS?.mountMember?.(),0)}
