function trialSignupScreen(message=''){commercialMode='public';setNav(false);app.innerHTML=`<section class="loginWrap"><div class="card loginCard"><div class="eyebrow">1 DÍA FULL · CUENTA PERSONAL</div><h1>Crea tu usuario de prueba</h1><p>Elige un usuario y una contraseña. Tendrás 24 horas FULL. Si después compras el acceso anual, <b>conservas exactamente este mismo usuario</b>: el administrador solo activa tu año.</p>${message?`<div class="loginMessage">${esc(message)}</div>`:''}<div class="field"><label>Tu nombre</label><input id="trialName" autocomplete="name" placeholder="Ej.: Sofía"></div><div class="field"><label>Usuario</label><input id="trialUser" autocomplete="username" placeholder="Ej.: sofia.paes"></div><div class="field"><label>Contraseña</label><input id="trialPass" type="password" autocomplete="new-password" placeholder="Mínimo 8 caracteres"></div><div class="field"><label>Repite tu contraseña</label><input id="trialPass2" type="password" autocomplete="new-password" placeholder="Repite la contraseña" onkeydown="if(event.key==='Enter')createTrialAccount()"></div><button class="btn full" onclick="createTrialAccount()">Activar mis 24 horas FULL</button><p class="tiny">Guarda tu usuario y contraseña. Los necesitarás para volver a entrar desde celular o computador.</p><div class="loginLinks"><button class="ghost" onclick="landing()">Volver</button><button class="ghost" onclick="loginScreen()">Ya creé mi usuario</button></div></div></section>`;window.scrollTo(0,0)}
async function createTrialAccount(){let client=await initSupabase();if(!client){trialSignupScreen('Primero debes conectar Supabase.');return}let display_name=($('#trialName')?.value||'').trim(),username=($('#trialUser')?.value||'').trim().toLowerCase().replace(/[^a-z0-9._-]/g,''),password=$('#trialPass')?.value||'',password2=$('#trialPass2')?.value||'';if(!display_name){trialSignupScreen('Escribe tu nombre.');return}if(!/^[a-z0-9._-]{3,40}$/.test(username)){trialSignupScreen('El usuario debe tener entre 3 y 40 caracteres y usar solo letras, números, punto, guion o guion bajo.');return}if(password.length<8){trialSignupScreen('La contraseña debe tener al menos 8 caracteres.');return}if(password!==password2){trialSignupScreen('Las contraseñas no coinciden.');return}let email=`${username}@paestrainer.app`;let {data,error}=await client.auth.signUp({email,password,options:{data:{trial:true,display_name,username}}});if(error){trialSignupScreen(error.message?.toLowerCase().includes('already')?'Ese usuario ya existe. Elige otro o entra con tu cuenta.':'No pudimos crear la prueba: '+error.message);return}if(!data?.session){trialSignupScreen('La cuenta se creó, pero Supabase está pidiendo confirmar correo. En Supabase debes desactivar Confirm email para permitir la prueba automática.');return}await new Promise(r=>setTimeout(r,350));await enterMember(data.session)}
function loginScreen(message=''){commercialMode='public';setNav(false);app.innerHTML=`<section class="loginWrap"><div class="card loginCard"><div class="eyebrow">ACCESO CLIENTES</div><h1>Iniciar sesión</h1><p>Usa el usuario y contraseña que te entregó el administrador.</p>${message?`<div class="loginMessage">${esc(message)}</div>`:''}<div class="field"><label>Usuario</label><input id="loginUser" autocomplete="username" placeholder="Ej.: catalina2027"></div><div class="field"><label>Contraseña</label><input id="loginPass" type="password" autocomplete="current-password" placeholder="Tu contraseña" onkeydown="if(event.key==='Enter')login()"></div><button class="btn full" onclick="login()">Entrar</button><div class="loginLinks"><button class="ghost" onclick="landing()">Volver</button><a href="${whatsappUrl()}" target="_blank" rel="noopener">Comprar acceso</a></div>${!isConfigured()?'<div class="setupWarning"><b>Modo de configuración:</b> aún falta conectar Supabase en <code>config.js</code>. La demo funciona igualmente.</div>':''}</div></section>`}
async function initSupabase(){if(!isConfigured()||!window.supabase)return null;if(!sb)sb=window.supabase.createClient(CFG.SUPABASE_URL,CFG.SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true}});return sb}
function deviceId(){let k='paesDeviceIdV1',v=localStorage.getItem(k);if(!v){v='d_'+(crypto.randomUUID?crypto.randomUUID():uid());localStorage.setItem(k,v)}return v}
async function login(){let client=await initSupabase();if(!client){loginScreen('Primero debes conectar Supabase. Sigue el README incluido en el ZIP.');return}let username=($('#loginUser')?.value||'').trim().toLowerCase().replace(/[^a-z0-9._-]/g,''),password=$('#loginPass')?.value||'';if(!username||!password){loginScreen('Escribe tu usuario y contraseña.');return}let {data,error}=await client.auth.signInWithPassword({email:`${username}@paestrainer.app`,password});if(error){loginScreen('Usuario o contraseña incorrectos.');return}await enterMember(data.session)}
async function fetchAccess(userId){let client=await initSupabase();let {data,error}=await client.from('user_access').select('*').eq('user_id',userId).single();if(error)return null;return data}
async function claimDevice(){let client=await initSupabase();let {data,error}=await client.rpc('claim_device',{p_device_id:deviceId()});if(error)return {ok:false,message:'No fue posible validar este dispositivo.'};return data}
async function enterMember(session){if(!session?.user){landing();return}let access=await fetchAccess(session.user.id);if(!access){await sb.auth.signOut();loginScreen('Esta cuenta no tiene una licencia asignada. Escríbenos por WhatsApp.');return}let now=Date.now(),expiry=new Date(access.access_until).getTime();if(!access.active||!expiry||expiry<=now){currentAccess=access;expiredScreen(access);return}currentAccess=access;commercialMode='member';ensureMemberProfile(access);setNav(true);syncGamification(getGame()).catch(()=>{});home()}
function ensureMemberProfile(access){let id=`member_${access.user_id}`,profiles=getProfiles(),p=profiles.find(x=>x.id===id);if(!p){p={id,name:access.display_name||access.username||'Estudiante',goal:750,studyProfile:'completas',tests:[],guest:false,member:true,created:new Date().toISOString()};profiles.push(p);saveProfiles(profiles)}else if(access.display_name&&p.name!==access.display_name){p.name=access.display_name;saveProfiles(profiles)}setActiveId(id)}
function expiredScreen(access){commercialMode='public';setNav(false);app.innerHTML=`<section class="loginWrap"><div class="card loginCard"><div class="expiredIcon">⌛</div><h1>${access?.access_type==='trial'?'Tu prueba FULL terminó':'Tu acceso ha vencido'}</h1><p>${access?.access_type==='trial'?'Tus 24 horas finalizaron. Tu usuario @'+esc(access.username)+' queda reservado para que, si compras, el administrador active el año completo sin cambiar tus credenciales.':'Tu licencia terminó el <b>'+new Date(access.access_until).toLocaleDateString('es-CL')+'</b>. Tu progreso local no se elimina.'}</p><a class="waBtn" href="${whatsappUrl()}" target="_blank" rel="noopener">${access?.access_type==='trial'?'Comprar y activar este usuario':'Renovar por 1 año'}</a><button class="ghost full" onclick="logout()">Cerrar sesión</button></div></section>`}
function deviceBlockedScreen(){commercialMode='public';setNav(false);app.innerHTML=`<section class="loginWrap"><div class="card loginCard"><div class="expiredIcon">🔐</div><h1>Revisa tu acceso</h1><p>Tu cuenta puede usarse en celular y computador. Si no puedes entrar, revisa usuario, contraseña y vigencia de la licencia.</p><a class="waBtn" href="${whatsappUrl()}" target="_blank" rel="noopener">Pedir ayuda por WhatsApp</a><button class="ghost full" onclick="landing()">Volver</button></div></section>`}
async function logout(){if(sb)await sb.auth.signOut();currentAccess=null;commercialMode='public';setActiveId('');landing()}
function daysLeft(){if(!currentAccess?.access_until)return 0;return Math.max(0,Math.ceil((new Date(currentAccess.access_until)-Date.now())/86400000))}
function account(){if(commercialMode==='trial'){trialAccount();return}let p=getActiveProfile();if(commercialMode!=='member'||!p){landing();return}let h=getHistory(),isAdmin=currentAccess?.role==='admin';app.innerHTML=`<h1>Mi cuenta</h1><section class="grid"><article class="card"><div class="profileSummary"><span class="avatar big">${esc((p.name||'P')[0].toUpperCase())}</span><div><h2>${esc(p.name)}</h2><p>@${esc(currentAccess?.username||'usuario')} · ${gradeLabel(p)} · ${esc(studyLabel(p))}</p></div></div><div class="licenseBox"><span>${currentAccess?.access_type==='trial'?'Prueba FULL activa':'Licencia activa'}</span><b>${currentAccess?.access_type==='trial'?Math.max(0,Math.ceil((new Date(currentAccess.access_until)-Date.now())/3600000))+' horas restantes':daysLeft()+' días restantes'}</b><small>${currentAccess?.access_type==='trial'?'Si compras, conservarás este mismo usuario.':'Vence: '+new Date(currentAccess.access_until).toLocaleDateString('es-CL')}</small></div>${(()=>{let g=getGame();return `<div class="meta"><span class="pill">🔥 ${g.streak} días</span><span class="pill">⭐ ${g.xp} XP</span><span class="pill">🏅 ${g.badges.length} medallas</span></div>`})()}<button class="secondary" onclick="gamification()">Ver racha y premios</button><button class="ghost" onclick="editProfile()">Editar perfil de estudio</button></article><article class="card"><h3>Privacidad y acceso</h3><p>Puedes iniciar sesión con tu cuenta en celular y computador. Cada navegador mantiene su progreso local; tu licencia sigue protegida por usuario, contraseña y fecha de vigencia.</p><div class="meta"><span class="pill">${h.length} sesiones guardadas aquí</span><span class="pill">📱💻 Multidispositivo</span></div><div class="toolbar"><button class="danger" onclick="clearMyData()">Borrar mi progreso local</button><button class="ghost" onclick="logout()">Cerrar sesión</button></div></article></section>${isAdmin?`<section class="adminCallout card"><div><div class="eyebrow">ADMINISTRADOR</div><h2>Gestión de clientes</h2><p>Crea accesos de 1 año, renueva, bloquea y cambia contraseñas.</p></div><button class="btn" onclick="adminPanel()">Abrir panel administrador</button></section>`:''}<div id="ratingMemberMount"></div><div class="toolbar"><button class="btn" onclick="home()">Volver al inicio</button></div>`;setTimeout(()=>window.PAES_RATINGS?.mountMember?.(),0)}
async function adminInvoke(body){let client=await initSupabase();let {data:ses}=await client.auth.getSession();let token=ses?.session?.access_token;if(!token)throw new Error('Sesión no válida');let res=await fetch(`${CFG.SUPABASE_URL}/functions/v1/admin-users`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`,'apikey':CFG.SUPABASE_PUBLISHABLE_KEY},body:JSON.stringify(body)});let data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Error del administrador');return data}
async function adminPanel(){if(currentAccess?.role!=='admin'){account();return}setNav(true);app.innerHTML=`<h1>Panel administrador</h1><section class="card"><div class="sectionTitle"><div><h2>Crear cliente · 1 año</h2><p>El usuario queda activo por 365 días y puede usar su cuenta en celular y computador.</p></div></div><div class="setup"><div class="field"><label>Nombre del alumno</label><input id="aname" placeholder="Ej.: Camila Pérez"></div><div class="field"><label>Usuario</label><input id="auser" placeholder="Ej.: camila2027"></div><div class="field"><label>Contraseña inicial</label><input id="apass" type="text" placeholder="Mínimo 8 caracteres"></div></div><div class="toolbar"><button class="btn" onclick="adminCreate()">Crear acceso por 1 año</button><button class="secondary" onclick="loadAdminUsers()">Actualizar lista</button><button class="ghost" onclick="account()">Volver</button></div><div id="adminNotice"></div></section><section class="sectionTitle"><div><h2>Clientes</h2></div></section><div id="adminUsers" class="card"><div class="empty">Cargando...</div></div><div id="adminRatings"></div>`;await loadAdminUsers();setTimeout(()=>window.PAES_RATINGS?.mountAdmin?.(),0)}
function adminNotice(msg,bad=false){let e=$('#adminNotice');if(e)e.innerHTML=`<div class="${bad?'adminError':'adminSuccess'}">${esc(msg)}</div>`}
async function adminCreate(){let display_name=$('#aname')?.value.trim(),username=$('#auser')?.value.trim().toLowerCase(),password=$('#apass')?.value||'';if(!display_name||!username||password.length<8){adminNotice('Completa nombre, usuario y una contraseña de al menos 8 caracteres.',true);return}try{await adminInvoke({action:'create_user',display_name,username,password});adminNotice(`Usuario ${username} creado con 365 días de acceso.`);$('#aname').value='';$('#auser').value='';$('#apass').value='';await loadAdminUsers()}catch(e){adminNotice(e.message,true)}}
async function loadAdminUsers(){let box=$('#adminUsers');try{let data=await adminInvoke({action:'list_users'}),users=data.users||[];box.innerHTML=users.length?users.map(u=>`<div class="adminUser"><div><b>${esc(u.display_name||u.username)}</b><small>@${esc(u.username)} · ${u.role==='admin'?'Administrador':(u.access_type==='trial'?'Prueba 24 h':'Cliente anual')}</small></div><div><span class="status ${u.active&&new Date(u.access_until)>new Date()?'good':'bad'}">${u.active?'Activo':'Bloqueado'}</span><small>Vence ${new Date(u.access_until).toLocaleDateString('es-CL')}</small>${u.game?`<small>🔥 ${u.game.streak||0} días · ⭐ ${u.game.xp||0} XP · Última actividad ${u.game.last_active_date?new Date(u.game.last_active_date+'T12:00:00').toLocaleDateString('es-CL'):'sin actividad'}</small>`:''}</div><div class="adminActions">${u.role!=='admin'?`<button class="ghost" onclick="adminAction('renew_user','${u.user_id}')">${u.access_type==='trial'?'Activar 1 año':'+1 año'}</button><button class="ghost" onclick="adminPassword('${u.user_id}')">Nueva clave</button><button class="${u.active?'danger':'secondary'}" onclick="adminAction('toggle_user','${u.user_id}',${!u.active})">${u.active?'Bloquear':'Activar'}</button><button class="danger" onclick="adminDelete('${u.user_id}','${esc(u.username)}')">Eliminar</button>`:''}</div></div>`).join(''):'<div class="empty">No hay clientes todavía.</div>'}catch(e){box.innerHTML=`<div class="adminError">${esc(e.message)}</div>`}}
async function adminAction(action,user_id,active){try{await adminInvoke({action,user_id,active});await loadAdminUsers()}catch(e){alert(e.message)}}
async function adminPassword(user_id){let password=prompt('Escribe la nueva contraseña (mínimo 8 caracteres):');if(!password)return;if(password.length<8){alert('Debe tener al menos 8 caracteres.');return}try{await adminInvoke({action:'reset_password',user_id,password});alert('Contraseña actualizada.')}catch(e){alert(e.message)}}
async function adminDelete(user_id,username){if(!confirm(`¿Eliminar definitivamente al usuario @${username}?\n\nSe borrarán su acceso, racha, XP y cuenta de inicio de sesión. Esta acción no se puede deshacer.`))return;let check=prompt(`Para confirmar, escribe ELIMINAR`);if(check!=='ELIMINAR'){alert('Eliminación cancelada.');return}try{await adminInvoke({action:'delete_user',user_id});alert(`Usuario @${username} eliminado.`);await loadAdminUsers()}catch(e){alert(e.message)}}
async function bootCommercial(){migrateLegacy();await initSupabase();if(sb){let {data}=await sb.auth.getSession();if(data?.session){await enterMember(data.session);return}}landing()}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});bootCommercial();
